SELECT h.hk_product AS product_hk, h.product_key, s.product_name, s.product_category, s.product_subcategory, s.brand, s.unit_cost, s.unit_price, cast(s.unit_price - s.unit_cost AS decimal(18,4)) AS unit_margin, s.is_discontinued, s.is_deleted, s.load_date AS valid_from, coalesce(s.load_end_date, timestamp'9999-12-31 23:59:59') AS valid_to, s.is_current, s.record_source FROM {processing}.raw_vault.hub_product h JOIN {processing}.raw_vault.sat_product s ON s.hk_product = h.hk_product
